const VARIATIONS = ['Morning', 'Evening', 'Noon', 'Afternoon', 'Dusk', 'Twilight', 'Sunrise', 'Midnight'];
// the Fonts door's pairs, by their plain names (mirrors FONT_PAIRS in gogh-editor.js)
