  ['eyebrow', 'heading', 'text', 'name'].forEach((k) => { if (band[k] != null && !str(band[k], 600)) bad(`${where}: band.${k} is too long.`); });
  if (band.rowGap != null && !['s', 'm', 'l'].includes(band.rowGap)) bad(`${where}: band.rowGap must be s, m or l.`);
